#!/usr/bin/env node
/**
 * bgdecor.mjs — что стоит в фоне страницы: рисунки, предметы на полях, буквы-призраки, узоры, свечения.
 *
 * Снимает с образца (донора) то, что лежит за содержимым и вокруг него, и кладёт в паспорт донора:
 * вид приёма, где он стоит, чем сделан, насколько он бледный — числом по снимку, — и чем такой же
 * приём сделать у себя. Тем же способом снимается своя сборка, и compare показывает, что из фона
 * донора у нас потерялось.
 *
 *   node bgdecor.mjs <url> [--pages "/,/menu"] [--viewport desktop,mobile] [--out <папка прогона>] [--tag имя]
 *                    [--no-crops] [--json файл|-] [--md файл]
 *   node bgdecor.mjs compare <донор.json> <url | наш.json> [--decisions файл] [--out <папка прогона>]
 *                    [--tag имя] [--viewport desktop,mobile] [--no-crops]
 *   node bgdecor.mjs selftest [--no-browser]
 *   node bgdecor.mjs --help | -h
 *
 * Выход: <папка>/decor/<tag>.json (протокол), <tag>.md (таблица для analysis.md и паспорта донора),
 * вырезки <папка>/decor/<tag>/b01.png … — слева место как на странице, справа само украшение отдельно
 * (бледное — с усиленным контрастом, иначе его не разглядеть); x01.png … — не засчитанное, чтобы
 * глазами проверить и отказ.
 *
 * Виды находок:
 *   drawing        рисунок в фоне: картинка, svg, фон-картинка без повтора или маска, которая служит украшением
 *                  (вне потока или под содержимым блока; pointer-events: none, aria-hidden, пустой alt —
 *                  подсказки, не условие), бледная и не мелкая (от 64 px по большей стороне), с резкими линиями
 *                  или краями — размытое пятно без рисунка идёт в glow. Бледная картинка в потоке, на которой нет
 *                  текста, — иллюстрация содержимого, не фон; то же — картинка вне потока, под которую заведён свой
 *                  блок: в блоке, относительно которого она поставлена, вне её закрашенной коробки меньше 20 знаков
 *                  текста (иллюстрации ячеек laravel.com: svg absolute в коробке заданной высоты);
 *   ghost-word     буквы-призраки: слово или буквы очень крупным кеглем (от 64 px и от 3,5 основного кегля)
 *                  с очень низким контрастом; или картинка-слово — бледный ряд из трёх и более знаков
 *                  (так сделаны грузинские буквы mamuka.rest: это svg в фоне, а не текст). Слово — одна строка
 *                  разных по форме знаков; одинаковые фигуры в несколько рядов (сетка плиток cal.com) — узор;
 *   margin-object  предмет или орнамент на полях: заметное (не бледное) украшение вне потока сбоку от содержимого,
 *                  от 40×24 px. Заметная картинка в потоке — содержимое, даже у самого края (значок слева от ссылки
 *                  в списке gov.uk). Поле — одно из трёх: (1) вне колонки страницы у края окна или небольшой предмет
 *                  (до 160×160 px) в пустом месте сбоку от содержимого своей полосы; (2) обрезано краем окна или
 *                  разделом, который кончается у самого края окна; (3) на узком экране (телефон), где колонка
 *                  занимает всё окно, — небольшой предмет у края окна, не лежащий на карточке. Плюс «по набору»:
 *                  украшение того же семейства, что предметы на полях (тот же рисунок или соседи с одним классом и
 *                  именами файлов, различающимися цифрой), считается так же. Ряд из трёх и больше одинаково
 *                  устроенных соседей близкого размера на одной линии или в одном столбце — содержимое (логотипы,
 *                  награды, аватары, значки пунктов списка), не предметы; соседи на линии считаются и по дереву —
 *                  слайды ленты, уехавшие за край окна, в ряду стоят, хотя кандидатами не стали. Обёртки вне потока
 *                  без текста и ссылок рядом не считаются (россыпь: кирпичики tetris-game.tilda.ws), кроме стены
 *                  логотипов: от четырёх соседей на линии с ровным шагом и просветами, идущих через колонку
 *                  содержимого (копия дорожки бегущей строки, партнёры в артборде Tilda), — это ряд. Значок блока — не
 *                  предмет: предмет вне потока целиком в отступе (padding) блока, относительно которого поставлен,
 *                  в блоке текста от 20 знаков, сам блок — в колонке страницы (значок слева от заголовка формы
 *                  cal.com-подобных страниц). Раздел во всю ширину окна с предметом в боковом отступе — по-прежнему
 *                  поле. Картинка в своей обёртке — тоже не предмет: вынесена из потока, но заполняет (от половины
 *                  коробки) обёртку без текста, которая сама стоит в потоке, — место под неё отведено вёрсткой
 *                  (значок-улыбка headspace.com: img absolute в div 107×105, сосед текста по строке);
 *   pattern      узор: фон с повтором или повторяющийся градиент, в котором рисунок — крупные формы или редкие
 *                  знаки на ровном фоне (сетка точек); или узор одной картинкой — повтор в самом файле или svg
 *                  (матрица точек). Плитка с «шумным» именем (noise, grain, paper, texture…) и плитка, похожая на
 *                  зерно, — фактура: ею занимается texture.mjs, здесь строка «фактура — см. texture.mjs» с
 *                  названием слоёв;
 *   glow           свечение: размытое пятно света или цвета без рисунка — radial-gradient, блок с filter: blur(),
 *                  заливка под маской radial-gradient, тень большого размытия или картинка, размытая в самом файле.
 *                  Свечение фона страницы — крупное: от 240 px по большей стороне и от 160 px по меньшей (мельче и
 *                  полоса света — украшение блока); на узком экране порог меньшей стороны — 0,32 ширины окна
 *                  (125 px при окне 390), если это меньше. У пятна, срезанного краем окна, меньшая сторона считается
 *                  вместе с частью коробки, ушедшей за край.
 *                  На поле свечение остаётся свечением, а не предметом: воспроизводится оно градиентом или
 *                  размытием, а не вырезкой. В строке находки — размер ядра (где пятно сильнее половины) и цвет
 *                  центра, в заметках — чем сделано у образца.
 * Не считаются: фото и картинки содержимого, логотип, иконки в кнопках и меню, аватары, карты, видео,
 * служебное Tilda, окно cookie, скрытое и обрезанное.
 *
 * Что внутри карточки — не фон страницы. Карточка — блок со своим фоном, рамкой или тенью, меньше раздела: уже окна,
 * не выше 0,7 его высоты и не больше 0,35 его площади (на телефоне — уже окна хотя бы на 12 px и не больше половины
 * площади). Панель уже окна и не выше 0,7 его высоты — карточка при любой площади, если у неё рамка и тень или свой
 * фон (отличный от того, что под ней), скругление и хотя бы одно из двух: рамка или тень (панель-призыв cal.com:
 * белый фон, тень, скругление 12 px, рамки нет). Свет градиентом в фоне блока со скруглением,
 * рамкой или тенью — свет самой карточки. Бледная иллюстрация, цифра-призрак, блик в углу карточки — украшение блока или содержимое: в находки не идёт,
 * в выводе — строка «внутри карточек — не в счёт: N» с вырезками. Карточка ищется по месту на экране, а не по дереву:
 * рисунок, который лежит под карточкой и виден снаружи (наброски mamuka.rest), остаётся находкой.
 *
 * Строки вывода сверх видов — чтобы «находок нет» не читалось как «украшений нет»:
 *   внутри карточек — не в счёт        что было бы находкой, не стой оно в карточке;
 *   крупное за содержимым              заметная не сплошная картинка вне потока шириной от 0,45 окна (ленты
 *                                      generationx5.tech): видом не засчитана — посмотреть глазами по вырезке;
 *   на странице есть то, чего скрипт не меряет: холсты (с размерами), узлы с теневым DOM, фон-картинки на весь
 *                                      блок, фоны с повтором без замера.
 *
 * Как меряется бледность (по снимку, а не по CSS: у mamuka.rest рисунки с opacity 1, бледность — в самих
 * пикселях). Три снимка одного места: как есть; без украшения; только украшение на прозрачном фоне.
 *   контраст — отношение яркостей «с украшением / без» по видимым пикселям украшения (как в WCAG), берётся
 *              90-й перцентиль: самые заметные места рисунка;
 *   Δ        — средняя разница цвета с фоном, уровней 0–255 (по самому отличающемуся каналу): золотой
 *              орнамент на белом по яркости близок к фону (контраст 2), а по цвету далёк (Δ 114);
 *   видно    — какая доля украшения не закрыта содержимым: рисунок под карточкой — «не видно», не находка.
 * Бледное: контраст до 1,6 и Δ до 45. Приглушённое непрозрачностью (opacity по всем предкам до 0,6) — бледное при
 * контрасте до 2,2 и Δ до 70, если украшение видно и снялось отдельно. Скрытое в момент замера (непрозрачность 0) —
 * не находка: на снимках анимация вокруг. Ниже предела заметности (Δ меньше 4 при видимой площади меньше 1000 px²) —
 * не находка: тонкую линию такой бледности глаз не видит.
 * Буквы-призраки текстом: контраст до 1,7 и Δ до 50. Крупное слово с высоким контрастом — не призрак,
 * а заголовок: оно уходит в «не засчитано» с числом контраста.
 * Мерится видимая часть: страница прокручивается к украшению целиком (блоки с overflow: hidden не прокручиваются),
 * и то, что обрезано разделом или краем окна, меряется обрезанным — как его видит человек.
 *
 * Свечение. Рисунок от пятна отличает не бледность и не стили, а мелкие детали в самом украшении — по снимку
 * «только украшение» (альфа и яркость, сведённые к CSS px и сглаженные окном 3×3):
 *   резкий перепад — шаг между соседними пикселями не меньше 0,12 местного размаха (окно 48 px) и 0,7 уровня;
 *   резкость края  — какая доля суммы всех перепадов альфы набрана резкими;
 *   рисунок внутри — сколько резких перепадов (альфы или яркости) приходится на пиксель периметра коробки.
 * Свечение: резкость края до 0,25 и рисунок внутри до 0,8 (T.glowSharp, T.glowEdges — двигать там), и пятно гаснет
 * (в коробке есть пустое, или слабые 5% альфы не выше 0,35 сильных). Нормировка — на свой местный размах: линия
 * наброска с альфой 0,08 даёт перепады малые по величине, но каждый — в весь её размах, резкость около 1; пятно
 * набирает тот же размах сотнями мелких шагов, резкость 0. Прямой край обрезки (край раздела с overflow: hidden,
 * своя коробка у radial-gradient at 50% 0%) из счёта снимается — по одной горизонтальной и одной вертикальной
 * прямой: половина пятна у края блока остаётся пятном, а у круга и прямоугольника край остаётся.
 * Форма пятна. Мягкий край бывает не только у пятна: предмет не в фокусе, мазок широкой кистью и размытый набросок
 * резкостью края от пятна не отличаются. У картинки (img, svg, фон) поэтому проверяется форма — по тому же снимку:
 *   плато — какая доля площади (где альфа от 0,2 наибольшей) лежит на полной силе (альфа от 0,8 наибольшей): пятно
 *           света гаснет от середины, плато у него до 0,36; у формы с мягким краем — от 0,44. Порог 0,4;
 *   ядро  — насколько область «альфа от половины наибольшей» заполняет свою коробку: цельное пятно — от 0,67,
 *           линии (размытый набросок, мазок) — до 0,43. Порог 0,5.
 * Форма с мягким краем идёт прежним путём: бледная — рисунок, заметная на поле — предмет. Пятно стилями это не
 * касается. Затемнение по краям (середина прозрачнее краёв: виньетка поверх фото) — не свечение: «не засчитано».
 * Стили — только повод измерить и подсказка в заметках: размытый png без единого признака в CSS — свечение, а
 * radial-gradient с жёсткими стопами — круг с краем («не засчитано», фигура). Пятна стилями ищутся и сами:
 * radial-gradient с прозрачным стопом, блок с filter: blur() от 8 px, пустой блок с тенью от 40 px, пустой блок с
 * заливкой под маской radial-gradient; рисунком и предметом такой кандидат не становится. Одинаковые пятна (один
 * стиль на носителях одного размера: свет в ста карточках) меряются два раза, остальные получают тот же вердикт.
 *
 * Доводка 06.10.2026 (картинка в своей обёртке, стена логотипов, панель-карточка без рамки, порог свечения на узком
 * экране и свечение по набору — «полоса» от 100 px при засчитанном таком же свете с той же подписью элемента; столбец —
 * ряд, только если плотный: орнамент на поле в каждом разделе — предметы; вердикт «по образцу» пятнам одного стиля —
 * только при размере носителя в пределах 35%; на телефоне предмет на картинке содержимого — не поле; код ответа документа) проверена на стендах, двух ловушках проверяющего и шести живых сайтах на двух экранах
 * (zakroma.rest, mamuka.rest, headspace.com, cal.com, tetris-game.tilda.ws, resend.com). Набор истины из 17 сайтов и
 * двенадцать сайтов вне набора после неё НЕ перегонялись: счёт по набору ниже — до доводки.
 * На чём проверено (02.10.2026). Разметка глазами двумя разметчиками: 17 сайтов на экране компьютера, 5 из них — на
 * телефоне (истина и сценарий сверки — work-2026-10-02/corpus/bgdecor-truth.md и bgdecor-cal/_tools/score.mjs), стенды
 * скилла и проверяющего и двенадцать сайтов вне набора (по восьми из них правила доводились, четыре — проверка
 * готовых правил). Пороги бледности (1,6 и 45), слова (1,7 и 50) и свечения (0,25 и 0,8) этой
 * сверкой не сдвинуты: ни одна строка разметки из-за них не потеряна. Пороги, которые стоят в промежутке по одному-двум
 * сайтам, так и названы в таблице T: свечение фона от 240 px, предел заметности, карточка, плато и ядро, телефон,
 * «свой блок» у иллюстрации.
 * Переменная RW_BGD_RAW=1 кладёт в протокол замер каждого кандидата целиком (поле raw: место и числа по снимкам) —
 * чтобы пересчитать виды по новым порогам без браузера (settle); в обычной работе не нужна.
 *
 * Колонка содержимого — по текстовым блокам страницы (без шапки и закреплённого): левый и правый края,
 * взвешенные по числу знаков. Предмет на полях проверяется по своей полосе: что из содержимого (тексты,
 * картинки, карточки с заливкой) стоит на той же высоте; пусто — по колонке страницы. Сторона: за текстом
 * (под строками текста лежит хотя бы 2% рисунка), слева, справа, по центру — по окну. Раздел — ближайший
 * заголовок выше украшения (h1–h4 и крупные надписи: у mamuka.rest и zakroma.rest тегов h1–h6 почти нет).
 *
 * Флаги:
 *   --pages "/,/a"   страницы через запятую: каждая снимается на каждом экране, протокол один; путь с «/» — от корня ХОСТА, без него ("./", "a.html") — от папки адреса; у сайта в подпапке — "./,a.html"
 *   --viewport       экраны через запятую (пресеты lib.mjs или ШxВ@плотность); по умолчанию desktop.
 *                    --viewports — то же самое; в compare по умолчанию — экраны донора
 *   --out            папка прогона (по умолчанию runs/<адрес>, см. runDir в lib.mjs): туда decor/
 *   --tag            имя протокола и папки вырезок (буквы, цифры, «-», «_», «.»); по умолчанию — имя сайта
 *                    по адресу (mamuka-rest), в compare — compare
 *   --no-crops       не сохранять вырезки (замер по снимкам всё равно идёт)
 *   --json           куда записать протокол; «-» — JSON в stdout вместо текста
 *   --md             куда записать таблицу
 *   --decisions      compare: файл решений (по умолчанию <папка>/decor-decisions.json)
 *   --no-browser     selftest без стенда в браузере (сверка и флаги)
 *
 * compare: у донора вид есть, у нас нет — НЕТ; есть, но штук меньше и на 10 000 px страницы больше чем
 * вдвое реже — РЕЖЕ. И то и другое без записи в decor-decisions.json — WARN. Решения — json «ключ →
 * причина»: { "ghost-word": "слово раздела стоит в заголовке, второй слой не нужен",
 * "pattern:mobile": "на телефоне узор убран, как у донора" }; ключ — вид или вид:экран; ключи с «_» —
 * комментарии. Чего у донора нет, а у нас есть, печатается как «своё» — проверить, что это задумано.
 * Протоколы разных версий правил (поле version; до калибровки — 1, после — 2) и протокол без вида «свечение» по видам
 * не сравнимы: такие строки получают «НЕ СРАВНИМО» вместо РЕЖЕ и НЕТ, а первой строкой печати и compare.md идёт
 * «переснять донора» (или наш сайт).
 *
 * Окна (cookie, SITE_REWORK_DISMISS) перед замером закрываются, как у discover и cliche; окно, которое
 * осталось открытым, — WARN: снимки идут под ним, и контраст измерен неверно. Кроме проверки lib есть своя: закреплённый
 * блок от 3% окна с кнопкой или полем, который лежит поверх прокрученной страницы (подписка в углу, выбор страны), —
 * WARN «поверх страницы осталось окно» с подсказкой, что нажать; его содержимое в кандидаты не идёт.
 *
 * Вердикт: OK — снято; WARN — окно при замере, страница не прокрутилась до низа, часть кандидатов не
 * измерена (предел 70 на экран и ещё 24 пятна стилями; предел 12 фонов с повтором; свой стиль не вставился), пропуски
 * и несравнимые протоколы в compare; FAIL — только selftest.
 * Коды выхода: 0 — OK или WARN; 1 — FAIL selftest или неизвестный флаг; 2 — неверные аргументы или файл;
 * 3 — страница не открылась или браузер не запустился.
 *
 * Чего скрипт не видит: слово, набранное картинкой слитным письмом (один контур — считается рисунком);
 * украшения на холсте (canvas) и внутри теневого DOM, бледный рисунок, растянутый фоном на весь блок
 * (background-size: cover) — он неотличим от фото-подложки (всё это называется строкой «чего скрипт не меряет»);
 * обычную картинку или svg в потоке без признаков украшения (наклейка на углу фото тегом img, рисунок от руки
 * встроенным svg) — кандидатом не становится; узор, собранный из отдельных элементов или маской с повтором; шевроны и
 * значки на кромке фото (наполовину на содержимом — «украшение блока»); крупные предметы первого экрана внутри колонки
 * (больше 160×160 px, не обрезаны окном) — их от иллюстрации содержимого числами не отличить. Свечение: conic- и
 * linear-gradient без маски и размытия; пятно, обрезанное двумя противоположными краями или в самом ярком месте по
 * узкой стороне, — выходит фигурой с краем (свет по верхней кромке карточки raycast.com); пятно с зерном в самой
 * картинке при сильном зерне уйдёт в рисунки; заливка градиентом на весь блок без спада — фон блока, не пятно; свет,
 * сделанный затемнением вокруг (тёмная виньетка с прозрачной серединой), — «затемнение по краям», не свечение.
 * Телефон: предмет на поле шире 0,45 окна не засчитывается (иллюстрация). Только Chrome.
 * Файлы донора не копируются: рисунки, слова и предметы у себя — свои.
 *
 * Экспорт: KINDS, RECIPES, measurePage, summarize, compareDecor, loadDecisions, decorMarkdown, pixelStats,
 * classify, settle.
 */
