  /* карточка: самый маленький блок со своим фоном, рамкой или тенью, на который приходится не меньше половины видимой
     части коробки украшения. Сам носитель — когда украшение лежит в его фоне под его же содержимым (свет фоном
     карточки) или это его псевдоэлемент. Блок внутри носителя (дети размытой обёртки) — не карточка. overMedia — какая
     доля видимой части лежит на картинке или видео содержимого */
