      if (!p || p === body || p === de) { H = null; break; }
      const q = p.getBoundingClientRect(); const cover = q.width > 0 && q.height > 0 ? Math.max(0, Math.min(q.right, R.r) - Math.max(q.left, R.l)) * Math.max(0, Math.min(q.bottom, R.b) - Math.max(q.top, R.t)) / (q.width * q.height) : 0;
      const hasText = st.texts.some((t) => !t.decor && p.contains(t.el));
