      const list = []; let more = false;
      for (const t of st.texts) { if (t.decor || !H.contains(t.el) || inside(t.el)) continue; if (list.length >= 60) { more = true; break; } const q = t.el.getBoundingClientRect(); if (q.width > 0 && q.height > 0) list.push([Math.round(q.left - L), Math.round(q.top - Tp), Math.round(q.width), Math.round(q.height), t.len]); }
