      const cover = hq.width > 0 && hq.height > 0 ? Math.round(Math.max(0, Math.min(hq.right, R.r) - Math.max(hq.left, R.l)) * Math.max(0, Math.min(hq.bottom, R.b) - Math.max(hq.top, R.t)) / (hq.width * hq.height) * 100) / 100 : 0;
