  const outColumn = cx < column.left || cx > column.right;
  const smallObj = area <= T.marginSmallArea;
  const wideOk = bb.w <= Math.max(160, vw * T.marginWide);
  const sideOk = !overText && (leftOf || rightOf) && overlap <= bb.w * 0.35 && wideOk && (outColumn ? gap <= vw * T.marginGap : smallObj && !!loc.band);
  const lc = loc.cut || null;
  const edgeCut = !!lc && still && ((lc.left >= T.edgeCut && lc.edgeL <= T.edgeNear && bx <= lc.edgeL + 2) || (lc.right >= T.edgeCut && lc.edgeR >= vw - T.edgeNear && bx + bb.w >= lc.edgeR - 2));
  const narrow = vw < T.narrowVw && column.right - column.left >= vw * T.narrowColumn;
  const cutOk = edgeCut && outFlow && !overText && wideOk && (loc.overMedia || 0) <= T.overMedia && (!narrow || big <= vw * T.phoneMax);
  const attached = !!loc.card && (px.inCard ?? 0) > T.phoneCard;
  /* … и не на картинке содержимого: наклейка «−20 %» на фото товара — часть карточки товара, а не предмет на поле */
  const phoneOk = narrow && outFlow && still && !overText && !attached && (!T.phoneOverMedia || (loc.overMedia || 0) <= T.overMedia) && gap <= vw * T.phoneGap && big <= vw * T.phoneMax;
  /* предмет на поле стоит вне потока. Заметная картинка в потоке — содержимое, даже у самого края: значок слева от
     ссылки в списке (gov.uk), крайняя картинка ленты */
