  let outsideText = null;
  if (loc.holder) { outsideText = loc.holder.more ? 400 : 0; for (const [tx, ty, tw, th, len] of loc.holder.texts) if (tx + tw <= bb.x || tx >= bb.x + bb.w || ty + th <= bb.y || ty >= bb.y + bb.h) outsideText += len; }
  const framedIn = outFlow && outsideText != null && outsideText < T.holderText;
  const ownWrap = T.wrapCover > 0 && framedIn && !!loc.holder && loc.holder.flow === true && (loc.holder.cover ?? 0) >= T.wrapCover;
  const onMargin = !inCard && !blockIcon && !ownWrap && outFlow && (sideOk || cutOk || phoneOk);
