  if (px.noise > 0.2) notes.push('фон вокруг менялся между снимками (видео, анимация) — числа приблизительны');
  const cardText = inCard ? `внутри карточки ${loc.card.sig} (${loc.card.w}×${loc.card.h} px, ${loc.card.paint})` : '';
  const inCardSkip = (what, was) => ({ skip: `${what} ${cardText} — украшение блока, а не фон страницы: ${num}`, code: 'in-card', aside: 'in-card', was, side, where });
