    notes.push(`пятно без рисунка: резкость края ${soft.sharp}, рисунок внутри ${soft.edges}${soft.core ? `, ядро (от половины силы) ${soft.core.w}×${soft.core.h} px` : ''}${soft.center ? `, цвет центра ${soft.center}` : ''}, наибольшая альфа ${soft.peak}`);
    if (overEdge) notes.push(`срезано краем окна: за краем ${overEdge} px коробки — меньшая сторона считана с ними (${Math.round(Math.min(bb.w + overEdge, bb.h))} px)`);
