    const ink = rgb(soft.center), ca = rgb(px.color), cb = rgb(px.bg);
    if (ink && ca && cb && Math.max(...ink) - Math.min(...ink) < 40 && lumOf(...ca) < lumOf(...cb)) notes.push('серое и темнее фона — тень или затемнение, а не свет');
