      const spreadOf = grp.length > 1 ? { contrast: range(own.map((x) => x.contrast)), delta: range(own.map((x) => x.delta)), size: range(own.map((x) => (x.box ? Math.max(x.box.w, x.box.h) : null))), opacity: range(own.map((x) => x.opacity)) } : null;
      items.push({ id: iid, ...rest2, kindRu: KINDS[grp[0].kind].ru, count: grp.length,
        members: grp.map((x) => ({ selector: x.selector, host: x.host, y: x.box ? x.box.y : null, side: x.side, section: x.section, pseudo: /::(before|after)$/.exec(x.selector) ? RegExp.lastMatch : null, box: x.box || null, ...(x.alike ? { alike: true } : { contrast: x.contrast ?? null, delta: x.delta ?? null, opacity: x.opacity ?? null, visible: x.visible ?? null, fill: x.fill ?? null }), ...(x.raw ? { raw: x.raw } : {}) })),
        ...(spreadOf && Object.values(spreadOf).some(Boolean) ? { spread: spreadOf } : {}), crop: finalize(lead._crop, `${iid}.png`) });
