    let xn = 0;
    const skippedOut = skipped.map((s) => { const { _crop, k, host, key, ...rest2 } = s; const keep = _crop && (xn < 24 || s.aside) && s.code !== 'gone' && s.code !== 'failed'; let crop = null; if (keep) { xn++; crop = finalize(_crop, `x${String(xn).padStart(2, '0')}.png`); } else if (_crop) fs.rmSync(_crop, { force: true }); return { ...rest2, host, crop }; });
    const asideOf = (type) => skippedOut.filter((s) => s.aside === type).map((s) => ({ selector: s.selector, box: s.box || null, share: s.share ?? null, was: s.was || null, crop: s.crop, sourceText: s.sourceText }));
